style.css:
/* RED DEVIL 2008 — Magister */

:root {
  /* swap these colours if you want */
  --my-red: #c8102e;
  --my-dark: #111114;
  --my-card: #1c1c22;
  --my-text: #f5f5f5;
  --my-muted: #a5a5ad;
  --my-silver: #b9bbc2;
}

/* dark stadium atmosphere */
html, body {
  background: var(--my-dark) !important;
  color: var(--my-text) !important;
  font-family: "Arial", "Helvetica Neue", sans-serif !important;
}

/* navigation */
nav, aside, [role="navigation"] {
  background: #17171c !important;
  border-color: #34343b !important;
}

/* cards and dashboard panels */
section, article, [role="main"] > div {
  border-radius: 10px !important;
}

/* headings */
h1, h2, h3 {
  color: #fff !important;
  font-weight: 800 !important;
  letter-spacing: -0.5px !important;
}

/* links */
a {
  color: #ed2948 !important;
  transition: color .2s ease !important;
}

a:hover {
  color: #fff !important;
}

/* buttons */
button {
  border-radius: 6px !important;
  transition: .2s ease !important;
}

button:hover {
  filter: brightness(1.2) !important;
}

/* tables */
table {
  border-color: #393940 !important;
}

th {
  background: #292930 !important;
  color: #ed2948 !important;
}

td {
  border-color: #33333a !important;
}

/* inputs */
input, select, textarea {
  background: #24242b !important;
  color: white !important;
  border: 1px solid #494952 !important;
  border-radius: 6px !important;
}

/* selection */
::selection {
  background: #c8102e !important;
  color: white !important;
}
